effect.shader:
const vec3 W = vec3(0.2126,0.7152,0.0722);
vec4 s(vec2 uv){ return texture2DCv(inputImg.texture, uv); }
float lum(vec3 c){ return dot(c,W); }
void main(){
vec2 uv = acLayerNorm;
vec2 px = 1.0/acLayerSize;
vec4 c = s(uv);
float a = c.a;
float v = useLuma ? lum(c.rgb) : a;
float tl = useLuma?lum(s(uv+vec2(-px.x,-px.y)).rgb):s(uv+vec2(-px.x,-px.y)).a;
float tc = useLuma?lum(s(uv+vec2(0.0,-px.y)).rgb):s(uv+vec2(0.0,-px.y)).a;
float tr = useLuma?lum(s(uv+vec2(px.x,-px.y)).rgb):s(uv+vec2(px.x,-px.y)).a;
float ml = useLuma?lum(s(uv+vec2(-px.x,0.0)).rgb):s(uv+vec2(-px.x,0.0)).a;
float mr = useLuma?lum(s(uv+vec2(px.x,0.0)).rgb):s(uv+vec2(px.x,0.0)).a;
float bl = useLuma?lum(s(uv+vec2(-px.x,px.y)).rgb):s(uv+vec2(-px.x,px.y)).a;
float bc = useLuma?lum(s(uv+vec2(0.0,px.y)).rgb):s(uv+vec2(0.0,px.y)).a;
float br = useLuma?lum(s(uv+vec2(px.x,px.y)).rgb):s(uv+vec2(px.x,px.y)).a;
float gx = (tr + 2.0*mr + br) - (tl + 2.0*ml + bl);
float gy = (bl + 2.0*bc + br) - (tl + 2.0*tc + tr);
float g = length(vec2(gx,gy));
float e = smoothstep(edgeThreshold, 1.0, g);
float b = smoothstep(brightThreshold-0.02, brightThreshold+0.02, v);
float m = e*b;
float f = feather;
vec2 k = f*px;
float m1 = m;
m1 = max(m1, (useLuma?lum(s(uv+vec2(k.x,0.0)).rgb):s(uv+vec2(k.x,0.0)).a) * m);
m1 = max(m1, (useLuma?lum(s(uv+vec2(-k.x,0.0)).rgb):s(uv+vec2(-k.x,0.0)).a) * m);
m1 = max(m1, (useLuma?lum(s(uv+vec2(0.0,k.y)).rgb):s(uv+vec2(0.0,k.y)).a) * m);
m1 = max(m1, (useLuma?lum(s(uv+vec2(0.0,-k.y)).rgb):s(uv+vec2(0.0,-k.y)).a) * m);
m1 *= a;
gl_FragColor = vec4(vec3(m1), m1);
}
